package com.eventmanager.controller;
import com.eventmanager.dao.EventDAO; import com.eventmanager.model.*; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/events") public class EventServlet extends HttpServlet { protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(u==null||!"ORGANIZER".equals(u.role)){res.sendError(403);return;}Event e=new Event();e.organizerId=u.id;e.title=req.getParameter("title");e.description=req.getParameter("description");e.eventDate=req.getParameter("eventDate");e.eventTime=req.getParameter("eventTime");e.venue=req.getParameter("venue");try{new EventDAO().create(e);res.sendRedirect("dashboard");}catch(Exception x){throw new ServletException(x);}} }
